PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS series(id TEXT PRIMARY KEY,type TEXT NOT NULL,title TEXT NOT NULL,issuer TEXT NOT NULL,jurisdiction TEXT NOT NULL,currency TEXT NOT NULL,total_units INTEGER NOT NULL,status TEXT NOT NULL,immutable_hash TEXT NOT NULL,governed_hash TEXT NOT NULL,terms_json TEXT NOT NULL,evidence_json TEXT NOT NULL,created_at INTEGER NOT NULL,activated_at INTEGER);
CREATE TABLE IF NOT EXISTS governed_proposals(id TEXT PRIMARY KEY,series_id TEXT NOT NULL,governed_json TEXT NOT NULL,governed_hash TEXT NOT NULL,execute_after INTEGER NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL,executed_at INTEGER,FOREIGN KEY(series_id) REFERENCES series(id));
CREATE TABLE IF NOT EXISTS business_transactions(id TEXT PRIMARY KEY,series_id TEXT NOT NULL,merchant_id TEXT NOT NULL,location_id TEXT NOT NULL,terminal_id TEXT NOT NULL,product_id TEXT NOT NULL,amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,external_ref TEXT NOT NULL UNIQUE,occurred_at INTEGER NOT NULL,state TEXT NOT NULL,settled_at INTEGER,refunded_at INTEGER,reversed_at INTEGER,payload_hash TEXT NOT NULL,metadata_json TEXT NOT NULL,created_at INTEGER NOT NULL,FOREIGN KEY(series_id) REFERENCES series(id));
CREATE TABLE IF NOT EXISTS transaction_events(id INTEGER PRIMARY KEY AUTOINCREMENT,tx_id TEXT NOT NULL,state TEXT NOT NULL,at INTEGER NOT NULL,reason TEXT NOT NULL,provider_ref TEXT NOT NULL,FOREIGN KEY(tx_id) REFERENCES business_transactions(id));
CREATE TABLE IF NOT EXISTS holder_checkpoints(id INTEGER PRIMARY KEY AUTOINCREMENT,series_id TEXT NOT NULL,wallet TEXT NOT NULL,balance REAL NOT NULL,ts INTEGER NOT NULL,source_ref TEXT NOT NULL,UNIQUE(series_id,wallet,ts,source_ref),FOREIGN KEY(series_id) REFERENCES series(id));
CREATE TABLE IF NOT EXISTS distributions(id TEXT PRIMARY KEY,series_id TEXT NOT NULL,period_id TEXT NOT NULL,manifest_hash TEXT NOT NULL UNIQUE,pool_minor INTEGER NOT NULL,allocated_minor INTEGER NOT NULL,withheld_minor INTEGER NOT NULL,payout_asset TEXT NOT NULL,status TEXT NOT NULL,manifest_json TEXT NOT NULL,created_at INTEGER NOT NULL,funded_ref TEXT,payout_ref TEXT,UNIQUE(series_id,period_id),FOREIGN KEY(series_id) REFERENCES series(id));
CREATE TABLE IF NOT EXISTS entitlements(distribution_id TEXT NOT NULL,wallet TEXT NOT NULL,amount_minor INTEGER NOT NULL,weight REAL NOT NULL,status TEXT NOT NULL DEFAULT 'UNPAID',payout_ref TEXT,PRIMARY KEY(distribution_id,wallet),FOREIGN KEY(distribution_id) REFERENCES distributions(id));
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,ts INTEGER NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,detail_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_tx_series_state ON business_transactions(series_id,state,occurred_at);
CREATE INDEX IF NOT EXISTS idx_holder_series_ts ON holder_checkpoints(series_id,ts);
CREATE INDEX IF NOT EXISTS idx_ent_wallet ON entitlements(wallet);
